def compare_versions(a, b):
    """
    Compare two semantic version strings.

    Returns:
        -1 if a < b
         0 if a == b
         1 if a > b
    """
    def parse(v):
        core, _, rest = v.partition('+')          # ignore build metadata
        core, _, pre = core.partition('-')       # separate pre-release
        major, minor, patch = map(int, core.split('.'))
        pre_ids = pre.split('.') if pre else []
        return major, minor, patch, pre_ids

    def compare_id(id1, id2):
        num1 = id1.isdigit()
        num2 = id2.isdigit()
        if num1 and num2:
            n1, n2 = int(id1), int(id2)
            if n1 < n2:
                return -1
            if n1 > n2:
                return 1
            return 0
        if num1 and not num2:
            return -1
        if not num1 and num2:
            return 1
        # both non-numeric
        if id1 < id2:
            return -1
        if id1 > id2:
            return 1
        return 0

    maj_a, min_a, pat_a, pre_a = parse(a)
    maj_b, min_b, pat_b, pre_b = parse(b)

    # Compare major, minor, patch
    if maj_a != maj_b:
        return -1 if maj_a < maj_b else 1
    if min_a != min_b:
        return -1 if min_a < min_b else 1
    if pat_a != pat_b:
        return -1 if pat_a < pat_b else 1

    # Compare pre-release
    if not pre_a and not pre_b:
        return 0
    if not pre_a:
        return 1
    if not pre_b:
        return -1

    for id_a, id_b in zip(pre_a, pre_b):
        cmp = compare_id(id_a, id_b)
        if cmp != 0:
            return cmp

    # All shared identifiers equal; shorter list is lower
    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1
    return 0

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self._capacity = capacity
        self._cache = OrderedDict()

    def get(self, key):
        if key not in self._cache:
            return None
        value = self._cache.pop(key)
        self._cache[key] = value  # re-insert to mark as most recent
        return value

    def put(self, key, value):
        if key in self._cache:
            self._cache.pop(key)
        self._cache[key] = value
        if len(self._cache) > self._capacity:
            self._cache.popitem(last=False)

    def __len__(self):
        return len(self._cache)

    def keys(self):
        return list(self._cache.keys())

def flatten_dict(d, sep="."):
    """
    Return a new dictionary with nested dictionaries flattened into a single level.
    Keys are joined by `sep`. Only dictionaries are descended into; other values
    (including lists) are kept as they are. Empty nested dictionaries are kept
    as empty dictionaries under their key. The input dictionary is not modified.
    """
    if not isinstance(d, dict):
        raise TypeError("flatten_dict expects a dictionary as input")

    result = {}

    def _flatten(current, prefix):
        for key, value in current.items():
            if not isinstance(key, str):
                raise TypeError("All keys must be strings")
            new_key = f"{prefix}{sep}{key}" if prefix else key
            if isinstance(value, dict):
                if value:
                    _flatten(value, new_key)
                else:
                    result[new_key] = {}
            else:
                result[new_key] = value

    _flatten(d, "")
    return result

def append_unique(item, bucket=None):
    if bucket is None:
        bucket = []
    if item not in bucket:
        bucket.append(item)
    return bucket

def top_words(text, n):
    counts = {}
    for w in text.split():
        cleaned = w.strip('.,;:!?').lower()
        if cleaned:
            counts[cleaned] = counts.get(cleaned, 0) + 1
    sorted_words = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return [word for word, _ in sorted_words[:n]]

